import { expect, expectStatus, test } from "../../fixtures";

test.describe("rejecting one document sends the whole vendor back", () => {
  test("the rejected extraction keeps the reviewer's note", { tag: "@LIF-02" }, async ({ apiAs, factory }) => {
    // Arrange
    const { documents, extractions } = await factory.vendorInReview();
    const reviewer = await apiAs("reviewer");

    // Act
    const response = await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
      data: { decision: "reject", note: "Wrong counterparty" },
    });

    // Assert
    const body = await expectStatus(response, 200);
    expect(body.status).toBe("rejected");
    const stored = await factory.extraction(documents.contract.id, "reviewer");
    expect(stored.status).toBe("rejected");
    expect(stored.review_note).toBe("Wrong counterparty");
  });

  test("the vendor status becomes rejected", { tag: "@LIF-02" }, async ({ apiAs, factory }) => {
    // Arrange
    const { vendor, extractions } = await factory.vendorInReview();
    const reviewer = await apiAs("reviewer");
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
        data: { decision: "reject", note: "Wrong counterparty" },
      }),
      200,
    );

    // Act
    const response = await reviewer.get(`/api/vendors/${vendor.id}`);

    // Assert
    const body = await expectStatus(response, 200);
    expect(body.status).toBe("rejected");
  });

  test("audit records extraction.rejected then vendor.rejected", { tag: "@LIF-02" }, async ({ apiAs, factory }) => {
    // Arrange
    const { vendor, extractions } = await factory.vendorInReview();
    const reviewer = await apiAs("reviewer");

    // Act
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
        data: { decision: "reject", note: "Wrong counterparty" },
      }),
      200,
    );
    const trail = await expectStatus<{ items: { action: string; details: Record<string, unknown> }[] }>(
      await reviewer.get(`/api/vendors/${vendor.id}/audit`),
      200,
    );

    // Assert
    const actions = trail.items.map((item) => item.action);
    const rejectedAt = actions.indexOf("extraction.rejected");
    expect(rejectedAt, `actions: ${actions.join(", ")}`).toBeGreaterThanOrEqual(0);
    expect(actions[rejectedAt + 1]).toBe("vendor.rejected");
    expect(trail.items[rejectedAt].details.extraction_id).toBe(extractions.contract.id);
  });
});
